import { useEffect } from "react";
import { useNavigate, useParams, useSearchParams } from "react-router-dom";
import { isDatasetId, type DatasetId } from "../../entities/dataset";
import { type DatasetVersionId } from "../../entities/dataset-version";
import {
  useDatasetBootstrapQuery,
  useDatasetVersionCapacityQuery,
  useDatasetVersionSchemaSummaryQuery,
  useDatasetVersionSourceProvenanceQuery,
  useDatasetVersionsQuery,
  useVersionEpisodesQuery,
} from "../../features/datasets/api";
import { RegionState } from "../../features/datasets/components/RegionState";
import { datasetRegionStateForError } from "../../features/datasets/components/error-state";
import { routes, type DatasetDetailTab } from "../../features/datasets/routing";
import { useCapabilities } from "../../shared/auth/use-capabilities";
import datasetDetailQueryCodec from "./query-codec";
import "../../features/datasets/components/datasets.css";

const invalidDataset = "dataset_invalid" as DatasetId;
const invalidVersion = "version_invalid" as DatasetVersionId;
const tabs: readonly { id: DatasetDetailTab; label: string }[] = [
  { id: "overview", label: "概要" }, { id: "versions", label: "Versions" }, { id: "episodes", label: "Episodes" },
  { id: "schema", label: "Schema" }, { id: "sources", label: "来源" }, { id: "capacity", label: "容量" },
];

export function DatasetDetailPage() {
  const { datasetId: rawDatasetId } = useParams();
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const search = datasetDetailQueryCodec.parse(params);
  const capabilities = useCapabilities();
  const valid = isDatasetId(rawDatasetId);
  const datasetId = valid ? rawDatasetId as DatasetId : invalidDataset;
  const bootstrap = useDatasetBootstrapQuery(datasetId, valid && capabilities.has("dataset.read"));
  const versions = useDatasetVersionsQuery(datasetId, search, valid && search.tab === "versions" && capabilities.has("dataset_version.read"));
  const chosenVersionId = search.versionId ?? bootstrap.data?.suggestedVersionId ?? bootstrap.data?.currentReadyVersion?.versionId ?? invalidVersion;
  const hasChosenVersion = chosenVersionId !== invalidVersion;
  const episodes = useVersionEpisodesQuery(datasetId, chosenVersionId, search, valid && search.tab === "episodes" && hasChosenVersion && capabilities.has("episode.read"));
  const schema = useDatasetVersionSchemaSummaryQuery(datasetId, chosenVersionId, valid && search.tab === "schema" && hasChosenVersion && capabilities.has("data_schema.read"));
  const sources = useDatasetVersionSourceProvenanceQuery(datasetId, chosenVersionId, search, valid && search.tab === "sources" && hasChosenVersion && capabilities.has("dataset_version.read"));
  const capacity = useDatasetVersionCapacityQuery(datasetId, chosenVersionId, valid && search.tab === "capacity" && hasChosenVersion && capabilities.has("storage.overview.read"));

  const versionBoundTab = search.tab === "episodes" || search.tab === "schema" || search.tab === "sources" || search.tab === "capacity";
  useEffect(() => {
    if (!valid || !versionBoundTab || search.versionId || !hasChosenVersion) return;
    navigate(routes.datasetDetail.build({ datasetId, tab: search.tab, versionId: chosenVersionId }), { replace: true });
  }, [chosenVersionId, datasetId, hasChosenVersion, navigate, search.tab, search.versionId, valid, versionBoundTab]);

  if (!valid) return <main className="dataset-page" data-page-id="P06"><RegionState state="not-found" message="Dataset ID 格式无效。" /></main>;
  if (capabilities.loading || bootstrap.isPending) return <main className="dataset-page"><RegionState state="first-loading" /></main>;
  if (capabilities.failed || !capabilities.has("dataset.read")) return <main className="dataset-page"><RegionState state="forbidden" /></main>;
  if (bootstrap.isError) return <main className="dataset-page"><RegionState state={datasetRegionStateForError(bootstrap.error)} message={bootstrap.error instanceof Error ? bootstrap.error.message : undefined} onRetry={() => void bootstrap.refetch()} /></main>;
  const data = bootstrap.data;
  const changeTab = (tab: DatasetDetailTab) => navigate(routes.datasetDetail.build({
    datasetId,
    tab,
    ...((tab === "episodes" || tab === "schema" || tab === "sources" || tab === "capacity") && hasChosenVersion
      ? { versionId: chosenVersionId }
      : {}),
  }));

  return (
    <main className="dataset-page" data-page-id="P06">
      <header className="dataset-resource-header"><div><p className="dataset-eyebrow">Dataset detail</p><h1>{data.dataset.name}</h1><p><code>{datasetId}</code> · {data.dataset.description || "暂无描述"}</p></div></header>
      <nav className="dataset-tabs" aria-label="数据集详情分区">{tabs.map((tab) => <button type="button" className="dataset-tab" role="tab" aria-selected={search.tab === tab.id} key={tab.id} onClick={() => changeTab(tab.id)}>{tab.label}</button>)}</nav>

      {(search.tab === "overview") ? <>
        <section className="dataset-band"><div className="dataset-band-heading"><div><h2>概要</h2><p>所有统计来自同一授权范围；未知值不做推断。</p></div><span className={`dataset-status dataset-status--${data.dataset.availability.toLowerCase()}`}>{data.dataset.availability}</span></div><dl className="dataset-metrics"><div className="dataset-metric"><dt>Episodes</dt><dd>{data.summary.episodeCount}</dd></div><div className="dataset-metric"><dt>有效时长(ns)</dt><dd>{data.summary.effectiveDurationNs}</dd></div><div className="dataset-metric"><dt>源字节</dt><dd>{data.summary.sourceBytes}</dd></div><div className="dataset-metric"><dt>物理字节</dt><dd>{data.summary.requiredPhysicalBytes}</dd></div><div className="dataset-metric"><dt>待复核</dt><dd>{data.summary.pendingReviewVersionCount}</dd></div><div className="dataset-metric"><dt>已退回</dt><dd>{data.summary.returnedVersionCount}</dd></div><div className="dataset-metric"><dt>可处理草稿</dt><dd>{data.summary.actionableDraftCount}</dd></div><div className="dataset-metric"><dt>统计状态</dt><dd>{data.summary.calculationState}</dd></div></dl></section>
        <section className="dataset-band"><div className="dataset-band-heading"><div><h2>当前 Ready 版本</h2><p>只使用服务端返回的固定 versionId。</p></div>{data.currentReadyVersion ? <button type="button" className="dataset-button" onClick={() => navigate(routes.versionDetail.build({ datasetId, versionId: data.currentReadyVersion!.versionId }))}>打开 {data.currentReadyVersion.displayVersion}</button> : null}</div>{!data.currentReadyVersion ? <RegionState state="empty" message="该数据集尚无 Ready 版本。" /> : <p><code>{data.currentReadyVersion.versionId}</code> · Manifest {data.currentReadyVersion.manifestSha256.slice(0, 12)}…</p>}</section>
      </> : null}

      {search.tab === "versions" ? <section className="dataset-band"><div className="dataset-band-heading"><div><h2>Versions</h2><p>Version ID 稳定且不可变；不接受 latest/current。</p></div></div>{versions.isPending ? <RegionState state="first-loading" /> : versions.isError ? <RegionState state={datasetRegionStateForError(versions.error)} onRetry={() => void versions.refetch()} /> : versions.data.items.length === 0 ? <RegionState state="empty" /> : <div className="dataset-table-scroll"><table className="dataset-table"><thead><tr><th>版本</th><th>类型</th><th>状态</th><th>创建时间</th><th /></tr></thead><tbody>{versions.data.items.map((version) => <tr key={version.id}><td><strong>{version.displayVersion}</strong><small>{version.id}</small></td><td>{version.kind}</td><td><span className={`dataset-status dataset-status--${version.status.toLowerCase()}`}>{version.status}</span></td><td>{new Date(version.createdAt).toLocaleString()}</td><td><button type="button" className="dataset-link" onClick={() => navigate(routes.versionDetail.build({ datasetId, versionId: version.id }))}>打开</button></td></tr>)}</tbody></table></div>}</section> : null}

      {search.tab === "episodes" ? <section className="dataset-band"><div className="dataset-band-heading"><div><h2>Episodes</h2><p>基于固定 Dataset + Version + Episode 身份进入隐藏 Viewer。</p></div></div>{!hasChosenVersion ? <RegionState state="empty" message="没有可用于列出 Episode 的固定版本。" /> : episodes.isPending ? <RegionState state="first-loading" /> : episodes.isError ? <RegionState state={datasetRegionStateForError(episodes.error)} onRetry={() => void episodes.refetch()} /> : episodes.data.items.length === 0 ? <RegionState state="empty" /> : <div className="dataset-table-scroll"><table className="dataset-table"><thead><tr><th>Episode</th><th>Revision</th><th>任务</th><th>成功状态</th><th>复核投影</th></tr></thead><tbody>{episodes.data.items.map((episode) => <tr key={episode.episodeId}><td><button type="button" className="dataset-link" onClick={() => navigate(routes.episodeViewer.build({ datasetId, versionId: episode.versionId, episodeId: episode.episodeId, returnTo: routes.datasetDetail.build({ datasetId, tab: "episodes", versionId: episode.versionId }) }))}><strong>#{episode.ordinal + 1}</strong><small>{episode.episodeId}</small></button></td><td><code>{episode.selectedRevisionId}</code></td><td>{episode.task ?? "—"}</td><td>{episode.successState}</td><td>{episode.reviewStatus} · {episode.reviewFindingCount}</td></tr>)}</tbody></table></div>}</section> : null}

      {search.tab === "schema" ? !capabilities.has("data_schema.read") ? <RegionState state="forbidden" message="Schema 摘要需要 data_schema.read。" /> : !hasChosenVersion ? <RegionState state="empty" /> : schema.isPending ? <RegionState state="first-loading" /> : schema.isError ? <RegionState state={datasetRegionStateForError(schema.error)} onRetry={() => void schema.refetch()} /> : <section className="dataset-band"><h2>Schema Snapshot</h2><dl className="dataset-metrics"><div className="dataset-metric"><dt>Snapshot</dt><dd>{schema.data.snapshot.id}</dd></div><div className="dataset-metric"><dt>Version</dt><dd>{schema.data.snapshot.version}</dd></div><div className="dataset-metric"><dt>Channels</dt><dd>{schema.data.channelCount ?? "—"}</dd></div></dl><p>SHA-256 <code>{schema.data.snapshot.sha256}</code></p></section> : null}
      {search.tab === "sources" ? !hasChosenVersion ? <RegionState state="empty" /> : sources.isPending ? <RegionState state="first-loading" /> : sources.isError ? <RegionState state={datasetRegionStateForError(sources.error)} onRetry={() => void sources.refetch()} /> : <section className="dataset-band"><h2>安全来源证据</h2>{sources.data.items.length === 0 ? <RegionState state="empty" /> : <div className="dataset-table-scroll"><table className="dataset-table"><thead><tr><th>来源</th><th>Upload</th><th>Manifest</th><th>注册时间</th></tr></thead><tbody>{sources.data.items.map((item) => <tr key={item.provenanceId}><td>{item.sourceDisplayName ?? "已脱敏"}<small>{item.sourceId ?? "—"}</small></td><td><code>{item.uploadId}</code></td><td><code>{item.sourceManifestId}</code></td><td>{new Date(item.registeredAt).toLocaleString()}</td></tr>)}</tbody></table></div>}</section> : null}
      {search.tab === "capacity" ? !capabilities.has("storage.overview.read") ? <RegionState state="forbidden" message="容量事实需要 storage.overview.read。" /> : !hasChosenVersion ? <RegionState state="empty" /> : capacity.isPending ? <RegionState state="first-loading" /> : capacity.isError ? <RegionState state={datasetRegionStateForError(capacity.error)} onRetry={() => void capacity.refetch()} /> : <section className="dataset-band"><h2>容量事实</h2><dl className="dataset-metrics"><div className="dataset-metric"><dt>状态</dt><dd>{capacity.data.state}</dd></div><div className="dataset-metric"><dt>源字节</dt><dd>{capacity.data.sourceBytes ?? "未知"}</dd></div><div className="dataset-metric"><dt>必需物理字节</dt><dd>{capacity.data.requiredPhysicalBytes ?? "未知"}</dd></div><div className="dataset-metric"><dt>实际 OSS 字节</dt><dd>{capacity.data.actualOssBytes ?? "未知"}</dd></div></dl><p>Basis <code>{capacity.data.basisRevision}</code> · {new Date(capacity.data.calculatedAt).toLocaleString()}</p></section> : null}
    </main>
  );
}

export default DatasetDetailPage;
